"""Combines attempt-1.<variant>.json into attempt-1.json / attempt-1.md (run after validate.py for both variants)."""
import json
from collections import Counter
variants = ["aku-sbe-master-tr-v1", "aku-sbe-phd-tr-v1"]
data = {v: json.load(open(f"attempt-1.{v}.json", encoding="utf-8")) for v in variants}
NOT_ASSERTED = [
    ("page-number distance from the bottom edge / footer + header distance", "UNKNOWN", "source silent ('alt orta')", "12.5 mm (Word default, NOT_SPECIFIED; measured baseline 283.55 mm)", "guide §5.3"),
    ("H5 space before/after", "UNKNOWN", "not stated (6/6 INFERRED from H2-H4)", "6/6 pt", "spec headings.h5"),
    ("GİRİŞ / TARTIŞMA / KAYNAKÇA / EKLER title spacing", "UNKNOWN", "only 'tek satır' is explicit; 12/12 pt INFERRED", "12/12 pt single (first baseline 33.18 mm = 28.95 + 12 pt before)", "spec headings.unnumberedMainParts"),
    ("Space before at the top of a page after a forced page break (chapter heading first baseline 33.18 mm instead of 28.95 mm)", "UNKNOWN", "Word keeps space-before after a hard page break (AKU_DECISIONS); no source page demonstrates it", "33.18 mm", "AKU_DECISIONS Word layout model"),
    ("Spacing around table / figure / picture captions", "UNKNOWN", "table caption 0/0 pt EXPLICIT; figure/picture 0/0 INFERRED; 'Kaynak:' line and block quotes 6/6 pt non-source", "as stated", "spec captions.spacingBeforePt"),
    ("Tanıtım sheet window position / width", "UNKNOWN", "first baseline 228.34 mm (EK 1 only), width <= 80 mm (widest example line)", "228.34 mm, 80 mm wide", "spec outer-cover"),
    ("Programme line wording on the inner cover", "UNKNOWN", "printed exactly as typed (PROGRAM_NAME), no invented suffix", "-", "AKU_DECISIONS"),
    ("PhD jury size", "UNKNOWN", "rows appear when filled (max 6 members + 2 advisors)", "-", "spec cover.innerCover"),
    ("Equation numbering", "UNKNOWN", "never mentioned in the guide; engine default", "-", "spec equations.numbering"),
    ("Abstract maximum words, keywords <= 5", "UNKNOWN", "only 'bir sayfa'; the keyword count is author responsibility (no validator)", "-", "guide §2.4"),
    ("Footnote separator length", "NOT_SPECIFIED", "'yaklaşık 4 cm' (measured within +-2 mm)", "40 mm", "guide §6.4"),
]
KNOWN = [
    ("Table continuation caption: '(Devam)' is bold with the label", "The guide example (p.30) prints 'Tablo 1.' bold and '(Devam)' regular; the engine styles all text before {title} as the label. The text rule only prescribes the words. Not asserted."),
    ("Appendix list (EKLER DİZİNİ)", "Not generated by the engine: optional editable section typed by the author, formatted like the lists (limitation)."),
    ("Inner cover blank-line structure", "EK 2a (4/3/4/3, INFERRED) vs official Word forms (3-member 2/3/3/3, 5-member 2/3/2/2, TEMPLATE) vs guide text (silent): the Word forms' counts are implemented; with the guide's 12/16 pt at 1.5 lines the EK 2a counts overflow one sheet for a 4-line title (see source.notes)."),
    ("Official inner-cover DOCX forms (14 pt, 25 mm margins) vs guide text (16 pt title, 12 pt names, 25/25/30/30)", "CONFLICT recorded; the guide's explicit text wins. The spec did not analyse the DOCX forms (Ic_Kapak_*_2026.docx, Etik_Beyan_Formu_2022.docx, Enstitu_Onayi_Formu_2024.docx)."),
    ("katex dev dependency returns 504 (Outdated Optimize Dep) on the running dev server", "Environment noise: equations are not part of this target; the fixtures contain no equation so the export is clean."),
]
out = {"target": "aku-sbe", "attempt": 1, "date": "2026-10-02", "tool": "orchestration/validation/aku-sbe/validate.py (PyMuPDF per-character origins + DOCX XML)", "variants": {}, "notAsserted": NOT_ASSERTED, "knownDeviations": KNOWN}
for v, d in data.items():
    c = Counter(r["status"] for r in d["results"])
    out["variants"][v] = {"pdf": d["pdf"], "docx": d["docx"], "pages": d["pages"], "counts": dict(c), "results": d["results"]}
json.dump(out, open("attempt-1.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
md = ["# aku-sbe validation, attempt 1 (2026-10-02)", "",
      "Real TxtNote export path: `orchestration/tools/export.mjs` presses the editor's own PDF and Word buttons (Edge headless, genuine Times New Roman, `local-fonts`); measured with `validate.py` (PyMuPDF, per-character baselines; python XML for the DOCX). Expected values come from the 2026 SBE guide and the reviewed spec (`measurableChecks`), not from the template data.",
      "", "Fixtures: `orchestration/artifacts/aku-sbe/export/*.fixture.json` (deterministic, `build_fixtures.py`): outer sheet, inner cover, ethics, placeholder approval page, ÖZET, ABSTRACT, ÖN SÖZ, İÇİNDEKİLER, lists (5 tables / 4 figures / 3 pictures), symbols, GİRİŞ, 5 chapters with H1-H5 (incl. wrapped long headings), paragraphs, multi-page table with `(Devam)` caption, wrapped table cell, figures, pictures, `Kaynak:` lines, block quote, 6 footnotes, TARTIŞMA, KAYNAKÇA, EKLER DİZİNİ, EKLER. `aku-sbe-master-lt3` (fewer than 3 tables/figures/pictures) proves the lists are absent below the threshold.", ""]
md.append("## Summary"); md.append(""); md.append("| variant | PDF pages | PASS | FAIL | UNKNOWN |"); md.append("|---|---|---|---|---|")
for v, d in out["variants"].items():
    c = d["counts"]; md.append(f"| {v} | {d['pages']} | {c.get('PASS', 0)} | {c.get('FAIL', 0)} | {c.get('UNKNOWN', 0) + len(NOT_ASSERTED)} (not asserted, listed below) |")
md += ["", "No FAIL in either variant. All PASS rows hold for both exports; the checks are the spec `measurableChecks` (page size, margins, fonts, sizes, pitches, indents, paragraph gaps, headings, captions, tables, footnotes, bibliography, TOC and lists, page numbering, special pages) plus DOCX structure checks.", ""]
md.append("## Not asserted (UNKNOWN / NOT_SPECIFIED in the sources)"); md.append(""); md.append("| item | status | what the source says | value used |"); md.append("|---|---|---|---|")
for item, status, src, used, ev in NOT_ASSERTED: md.append(f"| {item} | {status} | {src} | {used} |")
md += ["", "## Known deviations / conflicts (recorded, not hidden)", ""]
for t, n in KNOWN: md.append(f"- **{t}**: {n}")
for v, d in out["variants"].items():
    md += ["", f"## Results: {v}", "", "| id | status | expected | actual | evidence |", "|---|---|---|---|---|"]
    for r in d["results"]:
        esc = lambda x: str(x).replace("|", "/").replace("\n", " ")[:170]
        md.append(f"| {r['id']} | {r['status']} | {esc(r['expected'])} | {esc(r['actual'])} | {esc(r['evidence'])} |")
open("attempt-1.md", "w", encoding="utf-8").write("\n".join(md) + "\n")
print({v: d["counts"] for v, d in out["variants"].items()})
